class BulkProductUpdateError extends Error {
    constructor(
        message: string,
        public readonly details?: {
            failedId?: string;
            appliedIds?: string[];
            rollbackFailedIds?: string[];
        }
    ) {
        super(message);
        this.name = 'BulkProductUpdateError';
